#!/usr/bin/env bash
# Full pipeline (runs in the container, or locally with the same env vars):
#  1. copy Sources/*.sfdir to .font-build/ (Sources stay untouched)
#  2. import missing symbols + braille
#  3. build Normal TTF/OTF (the font's own ligatures are regenerated by fontbuilder)
#  4. patch with Nerd Fonts (single width) and restore the original family name
set -euo pipefail
cd "$(dirname "$0")/.."

work=.font-build
rm -rf "$work/src" Variants-nerd
mkdir -p "$work/src" export/nerd
cp -r Sources/FantasqueSansMono-*.sfdir "$work/src/"

fontforge -lang=py -script Scripts/import_symbols.py "$work"/src/FantasqueSansMono-*.sfdir

rm -rf "$work/out"
for s in "$work"/src/FantasqueSansMono-*.sfdir; do
    (cd Scripts && fontforge -quiet -lang=py -script build_normal.py "$OLDPWD/$s" "$OLDPWD/$work/out")
done

PATCHER_DIR=${PATCHER_DIR:-$work/patcher}
if [ ! -f "$PATCHER_DIR/font-patcher" ]; then
    mkdir -p "$PATCHER_DIR"
    curl -fsSL -o "$PATCHER_DIR/FontPatcher.zip" \
        "https://github.com/ryanoasis/nerd-fonts/releases/download/${NERD_FONTS_VERSION:-v3.5.1}/FontPatcher.zip"
    unzip -qo "$PATCHER_DIR/FontPatcher.zip" -d "$PATCHER_DIR"
fi

rm -f export/nerd/*
for f in "$work"/out/Normal/OTF/*.otf "$work"/out/Normal/TTF/*.ttf; do
    (
        tmp=$(mktemp -d)
        fontforge -lang=py -script "$PATCHER_DIR/font-patcher" --complete --mono \
            --no-progressbars --makegroups 0 -out "$tmp" "$f" >"$tmp/log" 2>&1 || { cat "$tmp/log"; exit 1; }
        out=$(ls "$tmp"/*.?tf)
        mv "$out" "export/nerd/$(basename "$f")"
        rm -rf "$tmp"
    ) &
done
wait
python3 Scripts/rename_family.py "Fantasque Sans Mono" export/nerd/*
python3 Scripts/terminal_tune.py export/nerd/*
